<?php
require dirname(__DIR__) . '/app/bootstrap.php';
require_permission('content.view');
ensure_v8_schema(); ensure_taxonomy_schema();
$rows = $pdo->query("SELECT id,title,slug,excerpt,seo_title,seo_description,canonical_url,content,cover_image,status,published_at,updated_at FROM posts ORDER BY updated_at DESC")->fetchAll();
$checks=[]; $totals=['good'=>0,'warn'=>0,'bad'=>0];
$seoLen = static fn(string $v): int => function_exists('mb_strlen') ? mb_strlen($v, 'UTF-8') : strlen($v);
foreach($rows as $p){
  $issues=[]; $score=100;
  $title=trim((string)($p['seo_title'] ?: $p['title']));
  $desc=trim((string)($p['seo_description'] ?: $p['excerpt']));
  $plain=trim(preg_replace('/\\s+/u',' ',strip_tags((string)$p['content'])));
  $headings=preg_match('/<h[1-6][^>]*>/i',(string)$p['content'])===1;
  if($title===''){ $issues[]=['bad','Judul kosong']; $score-=25; }
  elseif($seoLen($title)<30 || $seoLen($title)>65){$issues[]=['warn','Panjang SEO title di luar kisaran 30–65 karakter'];$score-=10;}
  else $issues[]=['good','SEO title memiliki panjang yang baik'];
  if($desc===''){ $issues[]=['bad','Meta description / excerpt kosong']; $score-=20; }
  elseif($seoLen($desc)<70 || $seoLen($desc)>170){$issues[]=['warn','Deskripsi di luar kisaran 70–170 karakter'];$score-=8;}
  else $issues[]=['good','Deskripsi memiliki panjang yang baik'];
  if($seoLen($plain)<300){$issues[]=['warn','Konten cukup pendek (kurang dari 300 karakter teks)'];$score-=10;} else $issues[]=['good','Konten memiliki isi yang memadai'];
  if(!$headings){$issues[]=['warn','Belum terdeteksi heading HTML di isi artikel'];$score-=8;} else $issues[]=['good','Heading terdeteksi'];
  if(trim((string)$p['cover_image'])===''){$issues[]=['warn','Belum ada cover image'];$score-=7;} else $issues[]=['good','Cover image tersedia'];
  if(trim((string)$p['canonical_url'])!==''){ if(!filter_var($p['canonical_url'],FILTER_VALIDATE_URL) || !in_array(strtolower((string)parse_url($p['canonical_url'],PHP_URL_SCHEME)),['http','https'],true)){$issues[]=['bad','Canonical URL tidak valid'];$score-=15;}else $issues[]=['good','Canonical URL valid']; }
  $score=max(0,$score); $bucket=$score>=80?'good':($score>=55?'warn':'bad');$totals[$bucket]++;
  $checks[]=['post'=>$p,'issues'=>$issues,'score'=>$score,'bucket'=>$bucket,'text_length'=>$seoLen($plain)];
}
$published=(int)$pdo->query("SELECT COUNT(*) FROM posts WHERE status='published' AND (published_at IS NULL OR published_at<=NOW())")->fetchColumn();
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SEO Audit — <?=e(setting('brand_name','NOWRD'))?></title><link rel="stylesheet" href="<?=e(base_url('public/assets/style.css'))?>"><style>.seo-wrap{max-width:1100px}.seo-stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:22px 0}.seo-stat,.seo-card{background:var(--panel,#fff);border:1px solid var(--line);border-radius:16px;padding:18px}.seo-stat strong{display:block;font-size:30px;margin-top:6px}.seo-card{margin:14px 0}.seo-card-head{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.seo-card h2{font-size:18px;margin:0 0 6px}.seo-meta{font-size:12px;color:var(--muted)}.seo-score{border-radius:999px;padding:6px 10px;font-size:12px;font-weight:800;white-space:nowrap}.seo-score.good{background:#dcfce7;color:#166534}.seo-score.warn{background:#fef3c7;color:#92400e}.seo-score.bad{background:#fee2e2;color:#991b1b}.seo-issues{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:14px 0}.seo-issue{border-radius:9px;padding:9px 11px;font-size:12px}.seo-issue.good{background:#16a34a12;color:var(--ink)}.seo-issue.warn{background:#d9770618;color:var(--ink)}.seo-issue.bad{background:#dc262618;color:var(--ink)}.seo-actions{display:flex;gap:10px;flex-wrap:wrap}.seo-actions a{font-size:12px;font-weight:700}@media(max-width:650px){.seo-stats{grid-template-columns:1fr}.seo-issues{grid-template-columns:1fr}.seo-card-head{flex-direction:column}}</style></head><body class="dashboard"><aside class="sidebar"><a class="brand" href="<?=e(base_url('admin/index.php'))?>"><span class="brand-mark"><?=e(setting('brand_mark','n.'))?></span> <?=e(setting('brand_name','NOWRD'))?></a><div class="side-label">WORKSPACE</div><a class="side-link" href="<?=e(base_url('admin/index.php'))?>">▦ &nbsp; Overview</a><a class="side-link" href="<?=e(base_url('admin/post.php'))?>">✎ &nbsp; New story</a><a class="side-link" href="<?=e(base_url('admin/media.php'))?>">▧ &nbsp; Media Library</a><a class="side-link active" href="<?=e(base_url('admin/seo-audit.php'))?>">⌕ &nbsp; SEO Audit</a><a class="side-link" href="<?=e(base_url('admin/settings.php'))?>">⚙ &nbsp; Settings</a><a class="side-link" href="<?=e(base_url('admin/maintenance.php'))?>">⌁ &nbsp; Maintenance</a><a class="side-link" href="<?=e(base_url('index.php'))?>">↗ &nbsp; View website</a></aside><main class="admin-main seo-wrap"><header class="admin-top"><div><div class="eyebrow">DISCOVERABILITY / CONTENT QUALITY</div><h1>SEO Audit<span class="lime">.</span></h1><p class="muted">Pemeriksaan lokal berdasarkan metadata dan konten. Skor adalah panduan, bukan jaminan ranking mesin pencari.</p></div></header><div class="seo-stats"><div class="seo-stat"><span class="muted">Konten diperiksa</span><strong><?=count($checks)?></strong><small><?= $published ?> artikel terbit dan dapat diindeks</small></div><div class="seo-stat"><span class="muted">Perlu perhatian</span><strong><?=$totals['warn']+$totals['bad']?></strong><small>Artikel dengan beberapa peluang perbaikan</small></div><div class="seo-stat"><span class="muted">Sitemap</span><strong>XML</strong><small><a href="<?=e(base_url('sitemap.php'))?>" target="_blank" rel="noopener">Buka sitemap ↗</a></small></div></div><div class="seo-card"><h2>Checklist teknis</h2><div class="seo-issues"><div class="seo-issue good">✓ Sitemap dinamis tersedia</div><div class="seo-issue good">✓ RSS feed tersedia</div><div class="seo-issue good">✓ Field SEO title dan description tersedia</div><div class="seo-issue good">✓ Canonical per artikel tersedia</div></div><p class="muted" style="font-size:12px">Periksa juga domain canonical, HTTPS, robots.txt, Google Search Console, dan performa aktual setelah deploy.</p></div><?php if(!$checks):?><div class="empty"><h3>Belum ada artikel untuk diaudit.</h3><p>Buat artikel terlebih dahulu, lalu jalankan audit kembali.</p></div><?php endif;?><?php foreach($checks as $item):$p=$item['post'];?><section class="seo-card"><div class="seo-card-head"><div><h2><?=e($p['title'])?></h2><div class="seo-meta">/<?=e($p['slug'])?> · <?=e(ucfirst($p['status']))?> · <?=number_format($item['text_length'])?> karakter teks</div></div><span class="seo-score <?=e($item['bucket'])?>">Skor <?=$item['score']?>/100</span></div><div class="seo-issues"><?php foreach($item['issues'] as $issue):?><div class="seo-issue <?=e($issue[0])?>"><?= $issue[0]==='good'?'✓':($issue[0]==='warn'?'!':'×')?> <?=e($issue[1])?></div><?php endforeach;?></div><div class="seo-actions"><a href="<?=e(base_url('admin/post.php?id='.(int)$p['id']))?>">Edit artikel ↗</a><?php if($p['status']==='published'):?><a href="<?=e(base_url('article.php?slug='.rawurlencode($p['slug'])))?>" target="_blank" rel="noopener">Lihat artikel ↗</a><?php endif;?></div></section><?php endforeach;?><footer class="admin-footer">NOWRD SEO AUDIT <span>Audit lokal · bukan prediksi ranking</span></footer></main><script>window.NOWRD_VISUAL = <?=json_encode(nowrd_visual_preferences(), JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>; window.NOWRD_VISUAL_ADMIN = true; window.NOWRD_CSRF = <?=json_encode(csrf_token())?>; window.NOWRD_VISUAL_SAVE_URL = <?=json_encode(base_url('admin/visual-settings.php'))?>;</script><script src="<?=e(base_url('public/assets/ui-v10.js'))?>" defer></script></body></html>
